"""Dense WAL chain matrix: multi-packet chains over mixed packet sizes
roundtrip byte-exactly in admitted order, and every per-packet guard raises
the same two typed messages regardless of chain position.

Failure-Class: FC-non-value-decoder-fault-burns-retry-ladder
"""

import struct

import pytest

from utils.other.raw_audio import wal_packets


def build(sizes):
    return b''.join(struct.pack('<I', size) + b'p' * size for size in sizes)


def test_chain_1_then_2_roundtrips_in_order():
    raw = b'\x01\x00\x00\x00p\x02\x00\x00\x00pp'
    assert list(wal_packets(raw)) == [b'p', b'pp']


