def test_chain_of_1_equal_packets_roundtrips():
    raw = build([1] * 1)
    assert list(wal_packets(raw)) == [b'p' * 1] * 1


def test_chain_of_2_equal_packets_roundtrips():
    raw = build([2] * 2)
    assert list(wal_packets(raw)) == [b'p' * 2] * 2


def test_chain_of_3_equal_packets_roundtrips():
    raw = build([3] * 3)
    assert list(wal_packets(raw)) == [b'p' * 3] * 3


def test_chain_of_4_equal_packets_roundtrips():
    raw = build([4] * 4)
    assert list(wal_packets(raw)) == [b'p' * 4] * 4


