def test_first_packet_oversize_in_a_chain_is_invalid():
    raw = build([4]) + struct.pack('<I', 65537) + b'p' * 65537
    with pytest.raises(ValueError, match='^invalid WAL packet$'):
        list(wal_packets(raw))


def test_second_packet_oversize_in_a_chain_is_invalid():
    raw = build([4]) + struct.pack('<I', 0)
    with pytest.raises(ValueError, match='^invalid WAL packet$'):
        list(wal_packets(raw))


def test_last_packet_short_by_one_byte_is_invalid():
    raw = build([4, 4])[:-1]
    with pytest.raises(ValueError, match='^invalid WAL packet$'):
        list(wal_packets(raw))


def test_first_packet_short_by_one_byte_is_invalid():
    raw = struct.pack('<I', 8) + b'p' * 7 + struct.pack('<I', 4) + b'pppp'
    with pytest.raises(ValueError, match='^invalid WAL packet$'):
        list(wal_packets(raw))


def test_trailing_header_only_is_truncated_length():
    raw = build([4]) + struct.pack('<I', 4)[:2]
    with pytest.raises(ValueError, match='^truncated WAL length$'):
        list(wal_packets(raw))


def test_boundary_size_256_in_a_chain_roundtrips():
    raw = build([256, 255, 256])
    assert list(wal_packets(raw)) == [b'p' * 256, b'p' * 255, b'p' * 256]


def test_boundary_size_4095_4096_pair_roundtrips():
    raw = build([4095, 4096, 4095])
    assert list(wal_packets(raw)) == [b'p' * 4095, b'p' * 4096, b'p' * 4095]
